css:
body :where([data-bz-node="tm"]) .bz-block{padding:0}
body :where([data-bz-node="tm"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="tm"]>.bz-container{padding-inline:0}

body [data-bz-node="tm"]{background:var(--paper);padding:100px 0 97px}
body [data-bz-node="tm"]>.bz-container{max-width:var(--container)}
body [data-bz-node="tm-head"] .bz-eyebrow{font:700 11px/1.4 var(--font-body);letter-spacing:.2em;text-transform:uppercase;color:#6b6b6a;margin:0 0 6px;margin-bottom:8px}
body [data-bz-node="tm-head"] h2{font:700 42.4px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0;font-size:40.3px}
body [data-bz-node="tm-grid"]{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:45px 1px 0;align-items:stretch}
body [data-bz-node^="tm-card-"]{grid-column:auto;display:flex;flex-direction:column;background:#fff;border:1px solid #d4d4d2;padding:21px 21px 20px;min-height:236px;box-sizing:border-box}
body [data-bz-node^="tm-quote-"] p{font:400 13px/23px var(--font-body);color:var(--ink);margin:0}
body [data-bz-node^="tm-name-"]{margin-top:auto}
body [data-bz-node^="tm-name-"] p{font:700 11.5px/1 var(--font-body);letter-spacing:.02em;color:var(--ink);margin:0}
body [data-bz-node^="tm-source-"] p{font:700 10.6px/1 var(--font-body);letter-spacing:.04em;color:#777;margin:9px 0 0}
@media (max-width:1100px){
  body [data-bz-node="tm"]{padding:0 24px 72px}
  body [data-bz-node="tm-head"] h2{font-size:34px}
  body [data-bz-node="tm-grid"]{grid-template-columns:1fr;gap:16px}
  body [data-bz-node^="tm-card-"]{min-height:0;gap:20px}
}
@media (max-width:640px){
  body [data-bz-node="tm"]{padding:0 20px 56px}
  body [data-bz-node="tm-head"] h2{font-size:28px}
}
